#!/usr/bin/env node
// Scan a captured conversation JSONL for friction signals.
// argv: <mode> ; reads JSONL on stdin.
//   mode=users   -> print real human user turns (non tool_result)
//   mode=errors  -> print tool_result entries flagged is_error, truncated
//   mode=summary -> counts + first/last timestamp + human-turn count
import { createInterface } from 'node:readline';

const mode = process.argv[2] || 'users';
const rl = createInterface({ input: process.stdin, crlfDelay: Infinity });

let n = 0, first = null, last = null, humans = 0, errs = 0;
const out = [];

const textOf = (content) => {
  if (typeof content === 'string') return content;
  if (!Array.isArray(content)) return '';
  return content.filter((b) => b && b.type === 'text').map((b) => b.text).join('\n');
};

for await (const line of rl) {
  if (!line.trim()) continue;
  let e;
  try { e = JSON.parse(line); } catch { continue; }
  n++;
  if (e.timestamp) { first ??= e.timestamp; last = e.timestamp; }
  const msg = e.message;
  if (e.type === 'user' && msg && msg.role === 'user') {
    const c = msg.content;
    const isToolResult = Array.isArray(c) && c.some((b) => b && b.type === 'tool_result');
    if (!isToolResult) {
      const t = textOf(c).trim();
      if (t) {
        humans++;
        if (mode === 'users') out.push(`\n--- HUMAN @${e.timestamp} ---\n${t.slice(0, 3000)}`);
      }
    } else if (Array.isArray(c)) {
      for (const b of c) {
        if (b && b.type === 'tool_result' && b.is_error) {
          errs++;
          if (mode === 'errors') {
            const s = typeof b.content === 'string' ? b.content : JSON.stringify(b.content);
            out.push(`\n--- ERR @${e.timestamp} ---\n${s.slice(0, 700)}`);
          }
        }
      }
    }
  }
  if (mode === 'assist' && e.type === 'assistant' && msg) {
    const t = textOf(msg.content).trim();
    if (t) out.push(`\n[A @${e.timestamp}] ${t.slice(0, 1200)}`);
  }
}

if (mode === 'summary') {
  console.log(JSON.stringify({ entries: n, first, last, humanTurns: humans, toolErrors: errs }));
} else {
  console.log(out.join('\n'));
}

#!/usr/bin/env node
// Pair each errored tool_result with the tool_use that caused it. Reads JSONL on stdin.
import { createInterface } from 'node:readline';
const rl = createInterface({ input: process.stdin, crlfDelay: Infinity });
const uses = new Map();
const out = [];
for await (const line of rl) {
  if (!line.trim()) continue;
  let e; try { e = JSON.parse(line); } catch { continue; }
  const msg = e.message;
  if (e.type === 'assistant' && msg && Array.isArray(msg.content)) {
    for (const b of msg.content) {
      if (b && b.type === 'tool_use') uses.set(b.id, { name: b.name, input: b.input, ts: e.timestamp });
    }
  }
  if (e.type === 'user' && msg && Array.isArray(msg.content)) {
    for (const b of msg.content) {
      if (b && b.type === 'tool_result' && b.is_error) {
        const u = uses.get(b.tool_use_id) || {};
        const inp = JSON.stringify(u.input || {}).slice(0, 400);
        const s = typeof b.content === 'string' ? b.content : JSON.stringify(b.content);
        out.push(`[${e.timestamp}] ${u.name}  ${inp}\n    -> ${s.replace(/\s+/g, ' ').slice(0, 260)}`);
      }
    }
  }
}
console.log(out.join('\n'));

